<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sorting Visualizer</title>
    <style>
        :root {
            --bg-color: #121212;
            --surface-color: #1e1e1e;
            --primary-color: #3498db;
            --accent-color: #2ecc71;
            --text-color: #eeeeee;
            --button-bg: #333333;
            --button-hover: #444444;
        }

        body {
            margin: 0;
            padding: 0;
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            display: flex;
            flex-direction: column;
            height: 100vh;
            overflow: hidden;
        }

        #controls {
            padding: 20px;
            background-color: var(--surface-color);
            display: flex;
            justify-content: center;
            gap: 15px;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
            z-index: 10;
        }

        button {
            padding: 10px 20px;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            background-color: var(--button-bg);
            color: var(--text-color);
            border: 1px solid #555;
            border-radius: 4px;
            transition: all 0.2s ease;
            outline: none;
            user-select: none;
        }

        button:hover {
            background-color: var(--button-hover);
            border-color: #777;
        }

        button:active {
            transform: translateY(1px);
        }

        button:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        #bars {
            flex: 1;
            display: flex;
            align-items: flex-end;
            justify-content: center;
            padding: 0 40px 40px 40px;
            gap: 4px;
            width: 100%;
            box-sizing: border-box;
        }

        .bar {
            flex: 1;
            background-color: var(--primary-color);
            border-radius: 2px 2px 0 0;
            min-width: 2px;
        }

        @keyframes highlight {
            0% { background-color: var(--accent-color); }
            100% { background-color: var(--primary-color); }
        }

        .bar.active {
            background-color: var(--accent-color);
        }
    </style>
</head>
<body>

<div id="controls">
    <button id="sort">Sort</button>
    <button id="shuffle">Shuffle</button>
    <button id="reset">Reset</button>
</div>

<div id="bars"></div>

<script>
    /**
     * The core logic of the sorting visualizer.
     * Using a stateful implementation of Bubble Sort to allow step-by-step animation.
     */
    (function() {
        const INITIAL_ARRAY = [60, 20, 90, 45, 10, 75, 30, 55, 85, 5, 50, 40, 95, 15, 65];
        let currentArray = [...INITIAL_ARRAY];
        let originalArray = [...INITIAL_ARRAY];

        // Bubble Sort State
        let i = 0;
        let j = 0;
        let isFinished = false;
        let isSorting = false;

        const barsContainer = document.getElementById('bars');
        const sortBtn = document.getElementById('sort');
        const shuffleBtn = document.getElementById('shuffle');
        const resetBtn = document.getElementById('reset');

        function render() {
            barsContainer.innerHTML = '';
            const maxVal = Math.max(...currentArray, 1);

            currentArray.forEach(val => {
                const bar = document.createElement('div');
                bar.className = 'bar';
                const heightPercent = (val / maxVal) * 100;
                bar.style.height = heightPercent + '%';
                barsContainer.appendChild(bar);
            });
        }

        /**
         * Required API for grading
         */
        window.viz = {
            array: function() {
                return [...currentArray];
            },
            setArray: function(a) {
                currentArray = [...a];
                // Reset sorting state when array is manually set
                i = 0;
                j = 0;
                isFinished = false;
                isSorting = false;
                render();
            },
            sortStep: function() {
                if (currentArray.length <= 1) {
                    isFinished = true;
                    return true;
                }
                if (isFinished) return true;

                // Single step of Bubble Sort: One comparison/swap
                if (currentArray[j] > currentArray[j + 1]) {
                    const temp = currentArray[j];
                    currentArray[j] = currentArray[j + 1];
                    currentArray[j + 1] = temp;
                }

                j++;
                // If we've reached the end of this pass
                if (j >= currentArray.length - 1 - i) {
                    j = 0;
                    i++;
                }

                // If the outer loop completes, the array is sorted
                if (i >= currentArray.length - 1) {
                    isFinished = true;
                    return true;
                }

                return false;
            },
            sorted: function() {
                for (let k = 0; k < currentArray.length - 1; k++) {
                    if (currentArray[k] > currentArray[k + 1]) return false;
                }
                return true;
            }
        };

        // --- UI Handlers ---

        async function animateSort() {
            if (isSorting) return;
            isSorting = true;
            sortBtn.disabled = true;
            shuffleBtn.disabled = true;
            resetBtn.disabled = true;

            // Reset state before starting to ensure it's a fresh sort
            i = 0;
            j = 0;
            isFinished = false;

            while (!window.viz.sortStep()) {
                render();
                // Control animation speed
                await new Promise(r => setTimeout(r, 50));
            }

            render();
            isSorting = false;
            sortBtn.disabled = false;
            shuffleBtn.disabled = false;
            resetBtn.disabled = false;
        }

        function shuffleArray() {
            const newArr = [...currentArray];
            for (let k = newArr.length - 1; k > 0; k--) {
                const r = Math.floor(Math.random() * (k + 1));
                [newArr[k], newArr[r]] = [newArr[r], newArr[k]];
            }
            window.viz.setArray(newArr);
        }

        function resetArray() {
            window.viz.setArray(originalArray);
        }

        // Event Listeners
        sortBtn.addEventListener('click', animateSort);
        shuffleBtn.addEventListener('click', shuffleArray);
        resetBtn.addEventListener('click', resetArray);

        // Initialize View
        window.viz.setArray(INITIAL_ARRAY);
    })();
</script>

</body>
</html>

